import { test, expect } from "@playwright/test";

test.use({ baseURL: process.env.WRECK_IT_BASE_URL ?? "http://localhost:4317", storageState: process.env.WRECK_IT_AUTH_MAIN ?? ".wreck-it/auth/main.json" });

/**
 * WR-009 [low · ux] Checkout accepts nonsense phone number
 * Expected: Invalid or empty phone is rejected with a specific message
 * Actual (bug): 201 order placed with phone 'not a phone'
 * Source: app/api/orders/route.ts:21 — Phone is never validated, only address is checked
 */
test("WR-009: Checkout accepts nonsense phone number", async ({ page, context }) => {
  const consoleErrors: string[] = [];
  const serverErrors: string[] = [];
  page.on("console", (m) => { if (m.type() === "error") consoleErrors.push(m.text()); });
  page.on("pageerror", (e) => consoleErrors.push(e.message));
  page.on("response", (r) => { if (r.status() >= 500) serverErrors.push(`${r.status()} ${r.url()}`); });
  let res: Awaited<ReturnType<typeof page.request.fetch>> | undefined;

  res = await page.request.fetch("/api/cart", { method: "POST", data: "{\"productId\": \"3\", \"quantity\": 1}" });
  res = await page.request.fetch("/api/orders", { method: "POST", data: "{\"address\":\"1 Wreck St\",\"phone\":\"not a phone\"}" });

  expect(res!.status()).toBeGreaterThanOrEqual(400);
});
